'use client';

import type { JSX, ReactNode, Ref } from 'react';
import {
  Button as RACButton,
  SearchField as RACSearchField,
  composeRenderProps,
  type SearchFieldProps as RACSearchFieldProps,
  type ValidationResult,
} from 'react-aria-components';
import { IconSearch, IconX } from '@tabler/icons-react';
import { Description, FieldError, FieldGroup, Input, Label } from './text-field';
import styles from './search-field.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

interface SearchFieldBaseProps extends Omit<RACSearchFieldProps, 'children' | 'aria-label' | 'aria-labelledby'> {
  description?: ReactNode;
  /** Shown when the field is invalid. A function receives React Aria's validation result. */
  errorMessage?: string | ((validation: ValidationResult) => string);
  placeholder?: string;
  /** Accessible name of the clear button. Defaults to React Aria's localized "Clear search". */
  clearLabel?: string;
  /** Ref to the underlying `<input>`. */
  inputRef?: Ref<HTMLInputElement>;
  ref?: Ref<HTMLDivElement>;
}

/** A search field needs a name: a visible `label`, or `aria-label` / `aria-labelledby` when the context makes it obvious. */
export type SearchFieldProps = SearchFieldBaseProps &
  (
    | { label: ReactNode; 'aria-label'?: string; 'aria-labelledby'?: string }
    | { label?: undefined; 'aria-label': string; 'aria-labelledby'?: string }
    | { label?: undefined; 'aria-label'?: string; 'aria-labelledby': string }
  );

/**
 * A search input with a leading icon and a clear button that appears once there is text.
 * Escape clears the field; Enter calls `onSubmit`.
 */
export function SearchField({
  label,
  description,
  errorMessage,
  placeholder,
  clearLabel,
  inputRef,
  className,
  ...rest
}: SearchFieldProps): JSX.Element {
  return (
    <RACSearchField {...rest} className={composeRenderProps(className, (c) => cx(styles.field, c))}>
      {label != null && <Label isRequired={rest.isRequired}>{label}</Label>}
      <FieldGroup className={styles.group}>
        <IconSearch className={styles.icon} aria-hidden="true" focusable="false" />
        <Input placeholder={placeholder} ref={inputRef} className={styles.input} />
        <RACButton className={styles.clear} aria-label={clearLabel}>
          <IconX aria-hidden="true" focusable="false" />
        </RACButton>
      </FieldGroup>
      {description != null && <Description>{description}</Description>}
      <FieldError>{errorMessage}</FieldError>
    </RACSearchField>
  );
}

/* Search field — the box comes from FieldGroup (text-field), so it matches every other input. Tokens only. */

.field {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--strata-space-2);
  min-inline-size: 0;
}

/* The clear button sits in the end padding, centred on the same inset as the block padding. */
.field .group {
  padding-inline-end: calc((var(--strata-control-height) - var(--strata-space-6)) / 2 - 1px);
}

.icon {
  flex: none;
  inline-size: var(--strata-space-4);
  block-size: var(--strata-space-4);
  color: var(--strata-color-text-subtle);
}

[data-disabled] .icon {
  color: var(--strata-color-text-disabled);
}

.input::-webkit-search-cancel-button,
.input::-webkit-search-decoration {
  appearance: none;
  display: none;
}

.clear {
  box-sizing: border-box;
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  inline-size: var(--strata-space-6);
  block-size: var(--strata-space-6);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: min(var(--strata-radius-field), var(--strata-space-1));
  background-color: transparent;
  color: var(--strata-color-text-subtle);
  cursor: pointer;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}

.clear > svg {
  inline-size: calc(var(--strata-space-4) - 2px);
  block-size: calc(var(--strata-space-4) - 2px);
}

.clear[data-hovered] {
  background-color: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
  color: var(--strata-color-text-default);
}

.clear[data-pressed] {
  background-color: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}

.clear[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}

/* Keep the space so the text never jumps when the first character is typed. */
.field[data-empty] .clear,
.field[data-disabled] .clear,
.field[data-readonly] .clear {
  visibility: hidden;
}

@media (prefers-reduced-motion: no-preference) {
  .clear {
    transition:
      background-color var(--strata-motion-duration-fast) var(--strata-motion-easing),
      color var(--strata-motion-duration-fast) var(--strata-motion-easing);
  }
}
